import { test, expect } from '@playwright/test';

test.describe('Live Data Timestamp Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/live-data');
  });

  test('should display last updated timestamp when live data is available', async ({ page }) => {
    // Wait for live data to load
    await page.waitForResponse(response => 
      response.url().includes('/api/live-data') && response.status() === 200
    );

    // Verify data container is visible
    const dataContainer = page.getByRole('region', { name: /live data/i });
    await expect(dataContainer).toBeVisible();

    // Verify timestamp element exists and is visible
    const timestampElement = page.getByText(/last updated/i);
    await expect(timestampElement).toBeVisible();

    // Verify timestamp contains a valid date format
    const timestampText = await timestampElement.textContent();
    expect(timestampText).toMatch(/last updated.*[0-9]{1,2} [a--zA-Z]{3,9} [0-9]{4}/);

    // Verify timestamp is not empty
    expect(timestampText).not.toBe('');
  });

  test('should display "No data available" message when live data fails to load', async ({ page }) => {
    // Intercept the API call and return an error
    await page.route('**/api/live-data', route => {
      route.abort('failed');
    });

    // Wait for the failed request
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText(/no data available/i);
    await expect(errorMessage).toBeVisible();

    // Verify timestamp element does not exist
    const timestampElement = page.getByText(/last updated/i);
    await expect(timestampElement).not.toBeVisible();

    // Verify data container shows error state
    const dataContainer = page.getByRole('region', { name: /live data/i });
    await expect(dataContainer).toContainText('No data available');
  });
});
